csv_st as (
  select c.*, row_number() over (partition by naziv order by rn) as k from csv c
),
idt as (
  select i.sifra, i.naziv, i.em,
         row_number() over (partition by i.naziv order by (i.klasifikat = '060') desc, coalesce(i.neaktiven, false), i.sifra) as k
  from public.spl_identi i
  where i.visible and i.naziv in (select naziv from csv)
)
insert into public.fp_vijacni_material (sifra, naziv, em, zaloga, lokacija, spremenjeno, spremenil)
select i.sifra, c.naziv, coalesce(nullif(upper(trim(i.em)), ''), 'KOS'), c.zaloga, c.lokacija,
       c.spremenjeno::timestamptz, c.spremenil
from csv_st c
left join idt i on i.naziv = c.naziv and i.k = c.k
order by c.rn;

-- Pregled: materiali brez šifre (naziv v ERP drugačen) - šifro se lahko vpiše ročno.
select id, naziv, zaloga, lokacija from public.fp_vijacni_material where sifra is null order by id;

